`timescale 1ns / 1ps
`include "effect_contract.svh"
`include "router_patch.svh"

// effect_bank.sv - GENERATED by scripts/fx.py from effects/registry.json, do not edit.
//
// One instance of every effect, addressed by router id.
//
//   * Every effect sees fx_sample, but only the one selected by fx_sel gets the
//     valid strobe, so the others' state (delay lines, LFO phase) advances only
//     on samples actually routed through them.
//   * Params are latched per effect on fx_params_load, one clock before the
//     strobe, and held until that effect is dispatched again: an effect may read
//     its params on any clock.
//
//   * An id with no instance (a retired effect, or a gap in the ids) passes the
//     sample straight through in the same clock, rather than leaving the router
//     to time out on an effect that does not exist.

module effect_bank (
    input  logic                             clk,
    input  logic                             rst_n,

    input  logic [`ROUTER_ID_W-1:0]          fx_sel,
    input  logic [`PARAM_BUS_WIDTH-1:0]      fx_params,
    input  logic                             fx_params_load,
    input  logic signed [`SAMPLE_WIDTH-1:0]  fx_sample,
    input  logic                             fx_valid,

    output logic signed [`SAMPLE_WIDTH-1:0]  fx_result,
    output logic                             fx_result_valid
);

    // ---- overdrive (id 1) ----------------------------------------------
    logic [`PARAM_BUS_WIDTH-1:0]     overdrive_params;
    logic signed [`SAMPLE_WIDTH-1:0] overdrive_out;
    logic                            overdrive_out_valid;
    wire                             overdrive_sel = (fx_sel == `FX_OVERDRIVE);

    always_ff @(posedge clk) begin
        if (!rst_n)
            overdrive_params <= '0;
        else if (fx_params_load && overdrive_sel)
            overdrive_params <= fx_params;
    end

    overdrive_top u_overdrive (
        .clk              (clk),
        .rst_n            (rst_n),
        .sample_in        (fx_sample),
        .sample_in_valid  (fx_valid && overdrive_sel),
        .params           (overdrive_params),
        .sample_out       (overdrive_out),
        .sample_out_valid (overdrive_out_valid)
    );

    // ---- distortion (id 2) ----------------------------------------------
    logic [`PARAM_BUS_WIDTH-1:0]     distortion_params;
    logic signed [`SAMPLE_WIDTH-1:0] distortion_out;
    logic                            distortion_out_valid;
    wire                             distortion_sel = (fx_sel == `FX_DISTORTION);

    always_ff @(posedge clk) begin
        if (!rst_n)
            distortion_params <= '0;
        else if (fx_params_load && distortion_sel)
            distortion_params <= fx_params;
    end

    distortion_top u_distortion (
        .clk              (clk),
        .rst_n            (rst_n),
        .sample_in        (fx_sample),
        .sample_in_valid  (fx_valid && distortion_sel),
        .params           (distortion_params),
        .sample_out       (distortion_out),
        .sample_out_valid (distortion_out_valid)
    );

    // ---- delay (id 3) ----------------------------------------------
    logic [`PARAM_BUS_WIDTH-1:0]     delay_params;
    logic signed [`SAMPLE_WIDTH-1:0] delay_out;
    logic                            delay_out_valid;
    wire                             delay_sel = (fx_sel == `FX_DELAY);

    always_ff @(posedge clk) begin
        if (!rst_n)
            delay_params <= '0;
        else if (fx_params_load && delay_sel)
            delay_params <= fx_params;
    end

    delay_top u_delay (
        .clk              (clk),
        .rst_n            (rst_n),
        .sample_in        (fx_sample),
        .sample_in_valid  (fx_valid && delay_sel),
        .params           (delay_params),
        .sample_out       (delay_out),
        .sample_out_valid (delay_out_valid)
    );

    // ---- echo (id 4) ----------------------------------------------
    logic [`PARAM_BUS_WIDTH-1:0]     echo_params;
    logic signed [`SAMPLE_WIDTH-1:0] echo_out;
    logic                            echo_out_valid;
    wire                             echo_sel = (fx_sel == `FX_ECHO);

    always_ff @(posedge clk) begin
        if (!rst_n)
            echo_params <= '0;
        else if (fx_params_load && echo_sel)
            echo_params <= fx_params;
    end

    echo_top u_echo (
        .clk              (clk),
        .rst_n            (rst_n),
        .sample_in        (fx_sample),
        .sample_in_valid  (fx_valid && echo_sel),
        .params           (echo_params),
        .sample_out       (echo_out),
        .sample_out_valid (echo_out_valid)
    );

    // ---- chorus (id 5) ----------------------------------------------
    logic [`PARAM_BUS_WIDTH-1:0]     chorus_params;
    logic signed [`SAMPLE_WIDTH-1:0] chorus_out;
    logic                            chorus_out_valid;
    wire                             chorus_sel = (fx_sel == `FX_CHORUS);

    always_ff @(posedge clk) begin
        if (!rst_n)
            chorus_params <= '0;
        else if (fx_params_load && chorus_sel)
            chorus_params <= fx_params;
    end

    chorus_top u_chorus (
        .clk              (clk),
        .rst_n            (rst_n),
        .sample_in        (fx_sample),
        .sample_in_valid  (fx_valid && chorus_sel),
        .params           (chorus_params),
        .sample_out       (chorus_out),
        .sample_out_valid (chorus_out_valid)
    );

    // ---- reverb (id 6) ----------------------------------------------
    logic [`PARAM_BUS_WIDTH-1:0]     reverb_params;
    logic signed [`SAMPLE_WIDTH-1:0] reverb_out;
    logic                            reverb_out_valid;
    wire                             reverb_sel = (fx_sel == `FX_REVERB);

    always_ff @(posedge clk) begin
        if (!rst_n)
            reverb_params <= '0;
        else if (fx_params_load && reverb_sel)
            reverb_params <= fx_params;
    end

    reverb_top u_reverb (
        .clk              (clk),
        .rst_n            (rst_n),
        .sample_in        (fx_sample),
        .sample_in_valid  (fx_valid && reverb_sel),
        .params           (reverb_params),
        .sample_out       (reverb_out),
        .sample_out_valid (reverb_out_valid)
    );

    always_comb begin
        case (fx_sel)
            `FX_OVERDRIVE:   begin fx_result = overdrive_out; fx_result_valid = overdrive_out_valid; end
            `FX_DISTORTION:  begin fx_result = distortion_out; fx_result_valid = distortion_out_valid; end
            `FX_DELAY:       begin fx_result = delay_out; fx_result_valid = delay_out_valid; end
            `FX_ECHO:        begin fx_result = echo_out; fx_result_valid = echo_out_valid; end
            `FX_CHORUS:      begin fx_result = chorus_out; fx_result_valid = chorus_out_valid; end
            `FX_REVERB:      begin fx_result = reverb_out; fx_result_valid = reverb_out_valid; end
            default:         begin fx_result = fx_sample; fx_result_valid = fx_valid; end
        endcase
    end

endmodule
